        # repeated diagonal marks are isolated deviations from this substrate.
        best_len, phase = -1, 0
        c = 0
        while c < w:
            if not row[c]:
                c += 1
                continue
            start = c
            while c+1 < w and row[c+1] and row[c+1] == row[c] % period + 1:
                c += 1
            if c-start+1 > best_len:
